CREATE TABLE t2(a,b PRIMARY KEY) WITHOUT ROWID; WITH RECURSIVE nums(value) AS (VALUES(1) UNION ALL SELECT value+1 FROM nums WHERE value<999) INSERT INTO t2(a,b) SELECT value,value FROM nums; UPDATE t2 SET a=NULL WHERE b%5=0; UPDATE t2 SET a=b, b=b+10000; CREATE INDEX t2a2 ON t2(a) WHERE a<100 OR a>200;